from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline FDTD-2D kernel: matches the PolyBench reference implementation.
@proc
def kernel_fdtd_2d(
    tmax: size,
    nx: size,
    ny: size,
    ex: DATA_TYPE[nx, ny] @ DRAM,
    ey: DATA_TYPE[nx, ny] @ DRAM,
    hz: DATA_TYPE[nx, ny] @ DRAM,
    _fict_: DATA_TYPE[tmax] @ DRAM,
):
    # Ensure the domain is large enough for the stencil accesses below.
    assert nx > 1
    assert ny > 1

    for t in seq(0, tmax):
        # Apply time-dependent boundary condition on the first row of ey.
        for j in seq(0, ny):
            ey[0, j] = _fict_[t]

        # Update ey using the magnetic field hz.
        for i in seq(1, nx):
            for j in seq(0, ny):
                ey[i, j] = ey[i, j] - 0.5 * (hz[i, j] - hz[i - 1, j])

        # Update ex using the magnetic field hz.
        for i in seq(0, nx):
            for j in seq(1, ny):
                ex[i, j] = ex[i, j] - 0.5 * (hz[i, j] - hz[i, j - 1])

        # Update hz using the updated electric fields ex and ey.
        for i in seq(0, nx - 1):
            for j in seq(0, ny - 1):
                hz[i, j] = hz[i, j] - 0.7 * (
                    ex[i, j + 1] - ex[i, j]
                    + ey[i + 1, j] - ey[i, j]
                )


# ----------------------------------------------------------------------
# Scheduling / optimization
#
# We keep the time loop (t) sequential to preserve the temporal
# dependency between time steps, and exploit spatial parallelism in
# the 2D grid. We:
#   - parallelize the simple ey boundary update over j,
#   - tile and parallelize the i-dimension of the three main 2D loops.
#
# Each parallelized loop maps to an OpenMP parallel-for in the
# generated C code.
# ----------------------------------------------------------------------

# Tile sizes for the i-dimension. These compile-time constants can be
# tuned for a given cache hierarchy / core count.
tile_i_ey = 32
tile_i_ex = 32
tile_i_hz = 32

# 1) Parallelize the ey boundary update:
#       for j in 0..ny-1: ey[0, j] = _fict_[t]
loop_ey_bc_j = kernel_fdtd_2d.find_loop("j")
kernel_fdtd_2d = parallelize_loop(kernel_fdtd_2d, loop_ey_bc_j)

# 2) Tile and parallelize the interior ey update:
#       for i in 1..nx-1, for j in 0..ny-1
#    We tile the i-dimension to improve cache locality across rows and
#    parallelize the outer tile loop.
loop_ey_i = kernel_fdtd_2d.find_loop("i")
kernel_fdtd_2d = divide_loop(
    kernel_fdtd_2d, loop_ey_i, tile_i_ey, ["i_ey_outer", "i_ey_inner"]
)
loop_ey_outer = kernel_fdtd_2d.find_loop("i_ey_outer")
kernel_fdtd_2d = parallelize_loop(kernel_fdtd_2d, loop_ey_outer)

# 3) Tile and parallelize the ex update:
#       for i in 0..nx-1, for j in 1..ny-1
loop_ex_i = kernel_fdtd_2d.find_loop("i")
kernel_fdtd_2d = divide_loop(
    kernel_fdtd_2d, loop_ex_i, tile_i_ex, ["i_ex_outer", "i_ex_inner"]
)
loop_ex_outer = kernel_fdtd_2d.find_loop("i_ex_outer")
kernel_fdtd_2d = parallelize_loop(kernel_fdtd_2d, loop_ex_outer)

# 4) Tile and parallelize the hz update:
#       for i in 0..nx-2, for j in 0..ny-2
loop_hz_i = kernel_fdtd_2d.find_loop("i")
kernel_fdtd_2d = divide_loop(
    kernel_fdtd_2d, loop_hz_i, tile_i_hz, ["i_hz_outer", "i_hz_inner"]
)
loop_hz_outer = kernel_fdtd_2d.find_loop("i_hz_outer")
kernel_fdtd_2d = parallelize_loop(kernel_fdtd_2d, loop_hz_outer)

# 5) Simplify algebra and remove any dead guards introduced by tiling.
kernel_fdtd_2d = simplify(kernel_fdtd_2d)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int tmax = TMAX;
  int nx = NX;
  int ny = NY;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(ex,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(ey,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(hz,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_1D_ARRAY_DECL(_fict_,DATA_TYPE,TMAX,tmax);

  /* Initialize array(s). */
  init_array (tmax, nx, ny,
	      POLYBENCH_ARRAY(ex),
	      POLYBENCH_ARRAY(ey),
	      POLYBENCH_ARRAY(hz),
	      POLYBENCH_ARRAY(_fict_));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten PolyBench views to 1D pointers. */
  kernel_fdtd_2d(/*ctxt=*/NULL, tmax, nx, ny,
                 (DATA_TYPE*)POLYBENCH_ARRAY(ex),
                 (DATA_TYPE*)POLYBENCH_ARRAY(ey),
                 (DATA_TYPE*)POLYBENCH_ARRAY(hz),
                 (DATA_TYPE*)POLYBENCH_ARRAY(_fict_));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nx, ny, POLYBENCH_ARRAY(ex),
				    POLYBENCH_ARRAY(ey),
				    POLYBENCH_ARRAY(hz)));

